MODULES=[
 dict(slug='supply-desk',name='Supply Desk',offer='Cross-location inventory exception board',title='Find the local<br><em>picture.</em>',desc='Put the item, the location and the uncertainty in the same view. Start with one high-variance device family.',user='Materials managers & supply-chain leaders',icon='inventory',scene='junction',problem='A stock number is only part of the story.',why='A dated ERP export, a physical count and a reserved lot can describe different quantities. The proposed board makes those distinctions visible before someone plans a transfer.',inputs=[('Item and unit','Local SKU, vendor identifier and a verified unit mapping.'),('Location and lot','Site, storage location, reservation and hold status.'),('Snapshot and owner','Inventory-as-of time, source reference and the next reviewer.')],steps=[('Locate','Connect the fictional item to North and South snapshots.'),('Reconcile','Separate on-hand, held and usable quantities. Leave unknown units unresolved.'),('Assign','Send the evidence packet to the responsible materials reviewer.')],boundary='Stock at another site does not authorize a transfer. Physical counts, ownership and purchasing constraints still need review.',proof='Test whether reviewers can reconstruct availability and ownership with less investigation effort than their existing workflow.',faqs=[('Does this replace an ERP?','No. The proposed starting point is a read-only coordination layer over authorized exports. An actual data path must be assessed.'),('What happens when counts disagree?','Keep both sources, their dates and the discrepancy visible. A materials reviewer resolves the conflict; the preview does not choose a true count.'),('What is the first pilot?','One high-variance device-family exception board at one hospital, with a sponsor, mapped inputs and an agreed historical baseline.')]),
 dict(slug='supply-review',name='Supply Review',offer='Demand and procedure-calendar scenario planner',title='Make the assumptions<br><em>visible.</em>',desc='Compare the usable snapshot with a stated demand scenario. Keep the planning window, units and unknowns attached.',user='Perioperative materials managers & service-line planners',icon='calendar',scene='arrival',problem='A procedure plan is not a consumption fact.',why='A schedule can change. An item-to-procedure assumption can be incomplete. Supply Review explores that uncertainty without changing a schedule or presenting a clinical recommendation.',inputs=[('Planning window','An agreed time period and synthetic procedure slots.'),('Demand assumption','Explicit assumed quantities, with the author and source.'),('Usable inventory','A dated, normalized quantity from the location being planned.')],steps=[('Set the window','Choose the period and document the assumed item demand.'),('Compare','Show the gap against the usable snapshot, not gross stock.'),('Review the scenario','Ask the service-line and materials reviewers to verify the assumptions.')],boundary='A potentially affected procedure is not a cancelled procedure. No patient details, schedule writes or treatment recommendations are involved.',proof='Evaluate whether the scenario exposes missing assumptions early enough for the operational team to review them.',faqs=[('Is the procedure calendar live?','No. Every slot in this preview is synthetic. Permission and a read-only schedule route are discovery questions.'),('What does the gap mean?','It is the difference between assumed demand and the displayed usable snapshot. It is not verified shortage impact or a clinical determination.'),('Can an unknown conversion be ignored?','No. Dependent calculations should abstain until the relevant unit relationship is verified.')]),
 dict(slug='supply-proof',name='Supply Proof',offer='Shortage/source monitoring with provenance',title='Every signal<br><em>has a source.</em>',desc='Keep the notice, the dates and the source attached. A public signal and a local stock count answer different questions.',user='Supply analysts & procurement coordinators',icon='source',scene='arrival',problem='A signal without context creates another handoff.',why='A notice may be old, refer to a different item or conflict with a later supplier update. Supply Proof proposes an evidence trail that keeps those questions open for a named reviewer.',inputs=[('Source reference','Original notice, supplier reference or public source URL.'),('Three times','Published or issued, retrieved and inventory-as-of dates.'),('Mapping context','The item association and any unresolved identifier mismatch.')],steps=[('Capture','Retain the original reference and dated source.'),('Compare','Expose stale, conflicting or unmapped evidence.'),('Attribute','Assign the next source review and preserve the explanation.')],boundary='The FDA medical device shortage list is a public signal, not a feed of a hospital’s stock or clinically safe substitutions.',proof='Test whether staff can explain where a shortage assumption came from and how fresh the supporting evidence is.',faqs=[('Is monitoring connected today?','No. These are proposed source workflows and fictional notices. Live monitoring is not an implemented capability.'),('Does a public shortage confirm a local gap?','No. Local inventory, demand and item mapping require separate evidence.'),('How are conflicting notices handled?','Both remain visible with their dates. The assigned source reviewer resolves the conflict or leaves it unresolved.')]),
 dict(slug='supply-signal',name='Supply Signal',offer='Substitution approval workflow involving clinicians and purchasing',title='The next move<br><em>is human.</em>',desc='Keep clinical-equivalence review and purchasing review distinct. Every proposed next step needs the right people.',user='Clinical reviewers, purchasing approvers & materials coordinators',icon='handoff',scene='review',problem='A candidate is not an approval.',why='Availability alone cannot establish clinical equivalence. A procurement clearance cannot replace a clinical review. The proposed workflow shows both responsibilities and holds when evidence is missing.',inputs=[('Candidate context','Fictional candidate identifier and the intended use under review.'),('Clinical evidence','Attributed equivalence status, restrictions and unresolved questions.'),('Purchasing evidence','Contract, availability and authorization constraints.')],steps=[('Present evidence','Record a candidate without selecting or recommending it.'),('Review separately','Clinical and purchasing roles inspect their own evidence.'),('Hold or hand off','Keep missing decisions blocked and preserve attributed review history.')],boundary='No automatic selection of clinically non-equivalent products. No external action, PO, message, stock movement or clinical determination occurs in this preview.',proof='Measure whether ownership, incomplete reviews and reasons for abstention are visible and understandable to both roles.',faqs=[('Does recording a demo review approve a substitute?','No. The controls only record that a fictional review occurred. A decision remains required, and no candidate is selected.'),('What if a clinical review is missing?','The handoff remains blocked. Purchasing activity cannot substitute for clinical-equivalence review.'),('Can decisions be corrected?','The proposed audit model retains actor, time and reason. This isolated preview can be reset without affecting any external system.')]),
 dict(slug='supply-report',name='Supply Report',offer='PO/receipt discrepancy and waste investigation',title='Investigate<br><em>the difference.</em>',desc='Set ordered, received and consumed evidence beside each other. Trace a discrepancy before assigning a cause.',user='Purchasing, receiving, inventory & finance reviewers',icon='receipt',scene='junction',problem='A variance is a question to investigate.',why='A short receipt, delayed delivery, unit mismatch or incomplete count can look similar in a spreadsheet. The proposed investigation preserves the source and the unresolved explanation.',inputs=[('PO and receipt','Dated line items, ordered and received quantities.'),('Unit contract','Explicit, approved units and any unresolved conversion.'),('Consumption and lots','Evidence needed to investigate expiry, loss or potential waste.')],steps=[('Align','Match the fictional PO and receipt references.'),('Check units','Calculate a difference only when the units are comparable.'),('Investigate','Assign an owner and retain alternative explanations.')],boundary='Potential waste is not a confirmed cause or a savings claim. No payment, accusation, write-back or automatic adjustment is made.',proof='Test whether a purchasing reviewer can trace a discrepancy to its evidence and explain the next investigation step.',faqs=[('Is a quantity difference automatically waste?','No. The cause remains unknown until supporting evidence is reviewed.'),('What if one record is in boxes?','The dependent difference is unresolved unless a verified BX-to-EA conversion exists.'),('Does the report update purchasing records?','No. The preview is read-only. Any future integration or external action requires separately defined permissions and human review.')])]

