 groups=[('Products',[('/products/','All modules')]+[(f'/products/{m["slug"]}/',m['name']) for m in MODULES]),('Platform',[('/platform/','Overview'),('/demo/','Synthetic demo'),('/data-and-integrations/','Data readiness'),('/governance/','Governance'),('/evaluation/','Evaluation')]),('Solutions',[('/solutions/','All solutions'),('/solutions/idn/','Health systems'),('/solutions/perioperative/','Perioperative teams'),('/solutions/partners/','GPO & ERP partners'),('/pilot-and-pricing/','Pilot & pricing')]),('Company',[('/company/','About'),('/why-wardrelay/','Why WardRelay'),('/resources/','Resources'),('/contact/','Contact'),('/sign-in/','Sign in')])]
