def button(url,label='Request a scoped pilot'):return link(url,label,'button')
def badge():return '<span class="preview-badge">DEMO / SYNTHETIC DATA</span>'
def crumbs(label):return f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><span>{label}</span></nav>'
def hero(label,title,desc,graphic='',scene='junction',cta='/request-pilot/',cta_label='Request a scoped pilot',photo=False):
 return f'''<section class="page-hero {'photo-hero' if photo else ''}" id="top" style="--scene:url('/assets/images/{scene}.webp')">{crumbs(label)}<div class="page-hero-grid"><div class="page-hero-copy"><p class="eyebrow">WARDRELAY / {label.upper()}</p><h1>{title}</h1><p class="hero-lead">{desc}</p><div class="page-actions">{button(cta,cta_label)}{link('#page-story','Explore the modules','quiet-link') if cta=='/demo/' else link('/demo/','Explore synthetic demo','quiet-link')}</div><p class="concept-note">Proposed workflows. Synthetic examples. Not an operating product.</p></div><div class="page-hero-art stagger-scene">{graphic}</div></div><div class="hero-walk-caption"><a href="#page-story"><span>↓</span> Follow the handoff</a><span>WARD WALK / CONCEPT PREVIEW</span></div><div class="page-route" aria-hidden="true"><svg viewBox="0 0 1400 150"><path d="M-20 100C250 170 290 0 600 65S1100 200 1420 40"/></svg></div></section>'''
def section(kicker,title,body,cls=''):return f'<section class="content-section {cls}"><div class="section-intro"><p class="eyebrow">{kicker}</p><h2>{title}</h2></div>{body}</section>'
def steps(items):
 return '<div class="process-steps">'+''.join(f'<article class="page-reveal" data-step="{i+1}"><span class="step-index">0{i+1}</span><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(items))+'</div>'

def cards(items):return '<div class="info-grid">'+''.join(f'<article class="info-card page-reveal"><span class="micro">0{i+1}</span><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(items))+'</div>'
def faq(items):return section('QUESTIONS, IN CONTEXT','Before the next handoff.','<div class="page-faq">'+''.join(f'<details><summary>{q}<span>+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>')
def cta(title='Bring one shortage<br>to the table.',desc='Start with a scoped reconstruction, a sponsor and the right reviewers.',url='/request-pilot/'):
 return f'<section class="page-cta"><svg aria-hidden="true" viewBox="0 0 1400 600"><path d="M-50 600C0 -130 1400 -130 1450 600"/></svg><p class="eyebrow">THE NEXT HANDOFF</p><h2>{title}</h2><p>{desc}</p>{button(url)}</section>'
def modules_grid():return '<div class="module-directory">'+''.join(f'<a class="module-directory-card page-reveal" href="/products/{m["slug"]}/"><span class="micro">0{i+1} / PROPOSED MODULE</span><img src="/assets/icons/{m["icon"]}.svg" alt=""><h3>{m["name"]}</h3><p>{m["offer"]}</p><span class="text-link">Explore the workflow <span>↗</span></span></a>' for i,m in enumerate(MODULES))+'</div>'
def panel(title,inside,kind=''):return f'<div class="artifact-panel {kind}"><div class="artifact-heading"><span class="micro">{title}</span>{badge()}</div>{inside}<div class="artifact-footer">12 OCT 2026 · FICTIONAL ROLE / NO EXTERNAL ACTION</div></div>'
def row(a,b):return f'<div class="evidence-row"><span>{a}</span><b>{b}</b></div>'

def visual(kind):
 if kind=='supply-desk':return panel('STOCK BY LOCATION','''<div class="facility-map"><button class="facility active" data-site="north"><img src="/assets/icons/inventory.svg" alt=""><span>North Demo</span><b>4 <small>EA usable</small></b></button><span class="map-bridge">↔</span><button class="facility" data-site="south"><img src="/assets/icons/inventory.svg" alt=""><span>South Demo</span><b>6 <small>EA usable</small></b></button></div><div id="facility-detail" aria-live="polite">'''+row('North on-hand','6 EA')+row('Reserved / held','2 EA')+row('Usable snapshot','4 EA')+'''</div><p class="artifact-warning">Select a location. Transfer requires review.</p>''')
 if kind=='supply-review':return panel('14-DAY SCENARIO','''<div class="scenario-dates">'''+''.join(f'<span class="{"scheduled" if i in [2,4,7,9,11,13] else ""}">{i+1:02}</span>' for i in range(14))+'''</div><label class="range-label" for="demand">Assumed item demand <b><output id="demand-value">6</output> EA</b></label><input id="demand" type="range" min="2" max="10" value="6"><div class="scenario-values"><div><span>North usable</span><b>4 <small>EA</small></b></div><div><span>Potential gap</span><b id="demand-gap">2 EA</b></div></div><p class="artifact-warning">Illustrative assumption. No schedule change or clinical recommendation.</p>''')
 if kind=='supply-proof':return panel('SOURCE EVIDENCE','''<div class="segmented"><button class="selected" data-proof="dated">Dated notice</button><button data-proof="conflict">Conflicting update</button></div><div class="evidence-timeline"><div><span>08:00</span><b>Notice issued</b><small>SRC-DEMO-12 / supplier signal</small></div><div><span>08:30</span><b>Source retrieved</b><small>Fictional source reviewer</small></div><div><span>09:00</span><b>Local snapshot</b><small>A separate inventory source</small></div></div><p id="proof-status" class="artifact-warning" aria-live="polite">Source linked. Local availability still requires stock evidence.</p>''')
 if kind=='supply-signal':return panel('TWO REVIEW LANES','''<div class="approval-lane"><span class="avatar">CR</span><div><b>Clinical reviewer</b><small>Equivalence evidence</small></div><button data-record-review="clinical">Record review</button></div><div class="approval-lane"><span class="avatar">PR</span><div><b>Purchasing reviewer</b><small>Contract and availability</small></div><button data-record-review="purchasing">Record review</button></div><p class="artifact-warning" id="approval-result" aria-live="polite">Both decisions pending. No substitute selected.</p><button class="reset-link" id="reset-reviews">Reset example</button>''')
 if kind=='supply-report':return panel('PO / RECEIPT INVESTIGATION','''<label class="unit-choice" for="receipt-unit">Receipt unit <select id="receipt-unit"><option value="EA">EA — verified same unit</option><option value="BX">BX — conversion unknown</option></select></label><div class="document-pair"><div><span>PO-DEMO-03</span><b>10 <small>EA</small></b><p>Ordered · 08:45</p></div><div><span>RCPT-DEMO-03</span><b>8 <small id="receipt-unit-label">EA</small></b><p>Received · 09:15</p></div></div><p class="artifact-warning" id="receipt-result" aria-live="polite">2 EA discrepancy. Cause unresolved; investigation required.</p>''')
 if kind=='trail':return panel('ONE SHARED EXCEPTION','''<div class="trail-stations">'''+''.join(f'<div><span>0{i+1}</span><img src="/assets/icons/{icon}.svg" alt=""><b>{name}</b><small>{note}</small></div>' for i,(icon,name,note) in enumerate([('source','Source','Dated notice'),('inventory','Stock','Two sites'),('calendar','Assumptions','Explicit demand'),('reviewer','Review','Human gate')]))+'''</div><p class="artifact-warning">The route stops at a person. No automatic external action.</p>''')
 if kind=='gate':return panel('READ-ONLY DISCOVERY','''<div class="mapping-lines"><span>PO / receipts</span><span>Inventory / consumption</span><span>Procedure assumptions</span></div><div class="mapping-gate"><img src="/assets/icons/lock.svg" alt=""><b>Permission + mapping gate</b><small>SKU / unit / freshness / owner</small></div><p class="artifact-warning">Proposed architecture. No live connection.</p>''')
 return visual('trail')

PAGES={}
def add(path,title,desc,content,bodyclass=''):PAGES[path]=dict(title=title,desc=desc,content=content,bodyclass=bodyclass)
for m in MODULES:
 related=[x for x in MODULES if x['slug']!=m['slug']][:2]
