add('/demo/','Synthetic Supply Desk demo','An isolated ten-record workbench with source evidence and manual review.',f'''<section class="demo-page-heading" id="top">{crumbs('Synthetic demo')}<div><div><p class="eyebrow">SUPPLY DESK / ISOLATED PREVIEW</p><h1>Follow the evidence.</h1><p>Ten fictional records. Every source, owner and unresolved question in view.</p></div>{badge()}</div></section><section class="demo-workspace"><div class="demo-toolbar"><label>Find a record<input type="search" id="demo-search" placeholder="Search item, owner or exception"></label><label>Review state<select id="demo-filter"><option value="all">All states</option><option>Pending</option><option>Blocked</option><option>Completed</option><option>Rejected</option></select></label><span id="demo-count" aria-live="polite">10 records</span><button class="reset-link" id="demo-reset">Reset demo</button></div><div class="demo-split"><aside class="demo-queue" aria-label="Synthetic exception queue" id="demo-queue"></aside><article class="demo-record" id="demo-record" aria-live="polite"></article><aside class="demo-sources" id="demo-sources" aria-label="Source evidence"></aside></div><div class="demo-bottom"><span>DEMO — SYNTHETIC DATA · CONCEPT PREVIEW · NO PHI OR LIVE CONNECTION</span><button class="text-link" id="demo-export">Download illustrative summary ↓</button></div></section><script type="application/json" id="synthetic-records">{json.dumps(RECORDS)}</script>'''+section('READ THE BOUNDARY','Reviewing is not authorizing.',cards([('Local only','Controls update this browser view. Reset or refresh clears the review session.'),('Human accountability','A materials review does not approve clinical equivalence or purchasing action.'),('Synthetic report','Downloads are labeled illustrative and contain only these fictional records.')]))+cta())

def environment(path,p):
 match=re.search(r"--scene:url\('/assets/images/(\w+)\.webp'\)",p['content'])
 first=match.group(1) if match else ('review' if path in ['/request-pilot/','/contact/'] else 'arrival')
 scenes=[first,'junction' if first!='junction' else 'arrival','review']
 return '<div class="walk-environment" aria-hidden="true">'+''.join(f'<img class="walk-photo photo-{i}" src="/assets/images/{scene}.webp" alt="" decoding="async" fetchpriority="{'high' if i==0 else 'low'}">' for i,scene in enumerate(scenes))+'<div class="walk-shade"></div><svg class="walk-trail" viewBox="0 0 1440 1000" preserveAspectRatio="none"><path d="M1320 -40 C1180 200 1430 310 1270 510 S1070 830 1380 1060" pathLength="1"/></svg></div><div class="walk-page-progress" aria-hidden="true"><span></span></div>'

# Assemble the complete website. Shared assets use root-relative URLs for nested pages.
def document(path,p):
 content=p['content'].replace('<section class="content-section', '<section id="page-story" class="content-section',1)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0e3a30"><title>{esc(p['title'])} | WardRelay</title><meta name="description" content="{esc(p['desc'])}"><link rel="canonical" href="{ORIGIN+path}"><meta property="og:title" content="{esc(p['title'])} | WardRelay"><meta property="og:description" content="{esc(p['desc'])}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/images/arrival.webp"><link rel="icon" href="/assets/logos/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/Manrope.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/funding.20261023.css"><link rel="stylesheet" href="/ward-walk.css"><script src="/site.js" defer></script><script src="/ward-walk.js" defer></script></head><body class="inner-page ward-journey {p['bodyclass']}" data-page="{path}"><a class="skip-link" href="#main">Skip to content</a>{header()}{environment(path,p)}<main id="main">{content}</main>{footer()}<button class="motion-control" id="site-motion" aria-pressed="false">Ⅱ Pause motion</button></body></html>'''
for path,p in PAGES.items():
 d=DIST/path.strip('/');d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(document(path,p).replace('type="submit"','type="submit" disabled'))
# Update only the homepage shell, leaving its approved visual sections in place.
home=DIST/'index.html';s=home.read_text();s=re.sub(r'<header class="site-header">.*?</header>\s*<div class="mobile-menu".*?</div>',lambda _:header(),s,count=1,flags=re.S)
s=re.sub(r'<footer class="site-footer">.*?</footer>',lambda _:footer(),s,count=1,flags=re.S)
s=s.replace('src="assets/','src="/assets/').replace('href="assets/','href="/assets/')
if '/site.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/funding.20261023.css"><script src="/site.js" defer></script></head>')
s=s.replace('<body>','<body data-page="home">')
dialog_routes={'pilot-dialog':'/request-pilot/','signin-dialog':'/sign-in/','privacy-dialog':'/privacy/','terms-dialog':'/terms/','about-dialog':'/company/'}
def convert(m):
 attrs,dialog,label=m.groups();route=dialog_routes.get(dialog,'/contact/');attrs=re.sub(r'\s*data-dialog="[^"]+"','',attrs);return f'<a{attrs} href="{route}">{label}</a>'
s=re.sub(r'<button((?=[^>]*data-dialog="([^"]+)")[^>]*)>(.*?)</button>',convert,s,flags=re.S)
# Give each module a dedicated destination in the suite strip; preserve the on-page selector.
s=re.sub(r'<a href="#products" data-module="([0-4])">',lambda m:f'<a href="/products/{MODULES[int(m[1])]["slug"]}/">',s)
s=s.replace('<a href="#demo" class="button secondary">','<a href="/demo/" class="button secondary">')
home.write_text(s)
ALIASES={'/pilot/':'/pilot-and-pricing/','/request-demo/':'/request-pilot/','/platform/data-readiness/':'/data-and-integrations/','/solutions/health-systems/':'/solutions/idn/','/legal/privacy/':'/privacy/','/legal/terms/':'/terms/','/about/':'/company/'}
for old,new in ALIASES.items():
 d=DIST/old.strip('/');d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Continue to WardRelay</title><link rel="canonical" href="{ORIGIN+new}"><meta http-equiv="refresh" content="0;url={new}"></head><body><a href="{new}">Continue to WardRelay</a></body></html>')
error=dict(title='Page not found',desc='Find your way back to WardRelay.',content='<section class="not-found" id="top"><p class="eyebrow">404 / THE TRAIL ENDS HERE</p><h1>Let’s find the<br>next handoff.</h1><p>This address does not match a page in the preview.</p><div class="page-actions">'+button('/','Return home')+link('/products/','Explore products')+link('/demo/','Open demo')+'</div></section>',bodyclass='')
(DIST/'404.html').write_text(document('/404.html',error))
(ROOT/'ROUTE-MANIFEST.json').write_text(json.dumps({'pages':['/']+list(PAGES),'aliases':ALIASES,'not_found':'/404.html'},indent=2))
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+p+'</loc></url>' for p in ['/']+list(PAGES))+'</urlset>')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n# Private concept preview; indexing can be reviewed for a future public launch.\n')
print(f'Built {len(PAGES)} supporting pages, {len(ALIASES)} route aliases and a custom 404. Homepage shell updated.')
